_desc_hit_chance.body:
static vector<string> _desc_hit_chance(const monster_info &mi)
{
    ostringstream result;
    describe_to_hit(mi, result, you.weapon());
    string str = result.str();
    if (str.empty())
        return vector<string>{};
    return vector<string>{str};
}

_desc_finite_wl.body:
static vector<string> _desc_finite_wl(const monster_info& mi)
{
    vector<string> r;
    const int wl = mi.willpower();
    if (wl == WILL_INVULN)
        r.push_back("infinite will");
    else
        r.push_back("susceptible");
    return r;
}

_desc_res_torment.body:
static vector<string> _desc_res_torment(const monster_info& mi)
{
    if (mi.resists() & (MR_RES_TORMENT))
        return { "not susceptible" };
    else
        return { "susceptible" };
}

_desc_see_invis.body:
static vector<string> _desc_see_invis(const monster_info& mi)
{
    vector<string> r;
    if (mi.can_see_invisible())
        r.push_back("can see invisible");
    else if (!mi.is(MB_CANT_SEE_YOU))
    {
        if (!you.backlit())
            r.push_back("will become unable to see you");
        else
            r.push_back("cannot see invisible");
    }
    return r;
}

_desc_slouch_damage.body:
static vector<string> _desc_slouch_damage(const monster_info& mi)
{
    if (!monster_at(mi.pos) || !you.can_see(*monster_at(mi.pos)))
        return vector<string>{};
    else if (!is_slouchable(mi.pos))
        return vector<string>{make_stringf("not susceptible")};
    else
        return vector<string>{make_stringf("damage: %dd3 / 2", slouch_damage(monster_at(mi.pos)))};
}

_desc_bind_soul_hp.body:
static vector<string> _desc_bind_soul_hp(const monster_info& mi)
{
    if (!monster_at(mi.pos) || !yred_can_bind_soul(monster_at(mi.pos)))
        return vector<string>{};
    return vector<string>{make_stringf("hp as a bound soul: ~%d", yred_get_bound_soul_hp(mi.type, true))};
}

_desc_marionette_spells.body:
static vector<string> _desc_marionette_spells(const monster_info& mi)
{
    if (mi.is(MB_SHADOWLESS) || mi.is(MB_SUMMONED) || mi.attitude != ATT_HOSTILE)
        return vector<string>();

    vector<mon_spell_slot> spells = get_unique_spells(mi);
    int num_spells = spells.size();
    int num_usable_spells = monster_at(mi.pos)->props[DITHMENOS_MARIONETTE_SPELLS_KEY].get_int();

    return vector<string>{make_stringf("%d/%d spells usable", num_usable_spells, num_spells)};
}

_desc_pacify_chance.body:
static vector<string> _desc_pacify_chance(const monster_info& mi, const int pow)
{
    vector<string> descs;

    if (mi.intel() <= I_BRAINLESS)
        descs.push_back("mindless");
    else if (!unpacifiable_reason(mi).empty()
             || _pacification_sides(mi.type, pow)
                <= _pacification_hp(mi.type) + 1)
        descs.push_back("uninterested");
    else
    {
        const int success = _pacify_chance(mi, pow, 100);
        if (success == 0)
            descs.push_back(make_stringf("chance to pacify: <<1%%"));
        else
            descs.push_back(make_stringf("chance to pacify: %d%%", success));
    }
    return descs;
}
